WITH x8 AS (SELECT x7.x2 AS x11 FROM x12), x9 AS (SELECT ROW_NUMBER() OVER (ORDER BY x7.x2) FROM x13) SELECT x7.v70489, x7.x2, ST_CROSSES(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION())'), ST_GEOMFROMTEXT('POINT(0 0)')) AS x4, x7.v70489 FROM v70786 AS x7 WHERE x7.x3 = '92' AND EXTRACT(MONTH FROM x7.v70489) = 2001